"""Module with tools to parse list of awaited messages defined in text format"""

from typing import Union, List, Type, Generic, TypeVar
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import AbstractInspector, HasInspector, NotHasInspector, \
    PassesInspector
from taf.rfrl.utilities.parsers.pcap_checker.exceptions import MessageDefinitionError


@dataclass
class Token:
    """
    Represents element in message tree definition.
    Examples of valid token: Token(name='name1', body=[Token(...)]), Token(name='other', body='Any object')
    """

    name: str
    body: Union[str, List['Token']]

    def is_name_empty(self) -> bool:
        """Returns True if Token has no name otherwise False."""

        return self.name == ''

    def is_body_empty(self) -> bool:
        """Returns True if Token has no body otherwise False."""

        return not self.body


@dataclass
class BracketCounter:
    """Counts number of pairs of opened brackets."""

    left_bracket: str
    right_bracket: str
    number_of_left_brackets: int = field(default=0)
    number_of_right_brackets: int = field(default=0)

    def increment(self, char: str, prev_char: str = '') -> None:
        """
        Increments counter values.
        Counter will be increment only if second parameter is different from '/' sign.
        """

        if char == self.left_bracket and prev_char != '\\':
            self.number_of_left_brackets += 1
        elif char == self.right_bracket and prev_char != '\\':
            self.number_of_right_brackets += 1

    def equals_zero(self) -> bool:
        """Returns True if no pair of brackets has been counted otherwise False."""

        return 0 == self.number_of_left_brackets == self.number_of_right_brackets

    def grater_then_zero(self) -> bool:
        """Returns True if any pair of brackets has been counted otherwise False."""

        return 0 < self.number_of_left_brackets == self.number_of_right_brackets > 0

    def reset(self) -> None:
        """Reset counting."""

        self.number_of_left_brackets = 0
        self.number_of_right_brackets = 0


class Tokenizer:
    """Dumps text to token tree."""

    def decompose_structure(self, text: str, left_bracket: str = '{', right_bracket: str = '}') -> Token:
        """Parses structure e.g: 'structureName { body... }' -> Token(name='structureName', body='body...')"""

        name, body, prev_char = '', '', ''
        counter = BracketCounter(left_bracket, right_bracket)

        for char in text:

            counter.increment(char, prev_char)

            if counter.equals_zero():
                name += char
            else:
                body += char

            if counter.grater_then_zero():
                name = name.strip()
                body = self._strip_one_left_char(body.strip(), left_bracket)
                body = self._strip_one_right_char(body, right_bracket)
                break

            prev_char = char

        return Token(name, body)

    def decompose_collection(self, text: str, left_bracket: str = '{', right_bracket: str = '}') -> List[Token]:
        """
        Parses collection of structures e.g:
        'structureName { body... }, structureName { body... }' ->
            [Token(name='structureName', body='body...'), Token(name='structureName', body='body...')]
        """

        structures = []
        raw_structure, prev_char = '', ''
        counter = BracketCounter(left_bracket, right_bracket)

        for char in text:

            raw_structure += char

            counter.increment(char, prev_char)

            if counter.grater_then_zero():

                structure = self.decompose_structure(raw_structure, left_bracket, right_bracket)

                if structure.is_name_empty():
                    raise MessageDefinitionError(f'Structure cannot be parsed: '
                                                 f'missing name of structure:\n{raw_structure}')
                if structure.is_body_empty():
                    raise MessageDefinitionError(f'Structure cannot be parsed: '
                                                 f'missing body of structure:\n{raw_structure}')

                structures.append(structure)
                raw_structure = ''
                counter.reset()

            prev_char = char

        if not counter.equals_zero():
            raise MessageDefinitionError('Structure cannot be parsed: '
                                         'number of opening brackets and number of closing brackets are not equal')

        if raw_structure.strip() != '':
            raise MessageDefinitionError(f'Structure cannot be parsed: '
                                         f'missing brackets in structure:\n {raw_structure}')

        return structures

    def tokenize(self, text: str) -> List[Token]:
        """Parses flow of messages defined as text."""

        messages = self.decompose_collection(text)

        for message in messages:
            sections = self.decompose_collection(message.body)

            for section in sections:
                section.body = self.decompose_collection(section.body, left_bracket='(', right_bracket=')')

            message.body = sections

        return messages

    @staticmethod
    def _strip_one_left_char(str_: str, char: str = ' ') -> str:
        """Works like str.lstrip method but cuts exactly one char from left side."""

        if len(str_) > 0 and str_[0] == char:
            str_ = str_[1:]
        return str_

    @staticmethod
    def _strip_one_right_char(str_: str, char: str = ' ') -> str:
        """Works like str.rstrip method but cuts exactly one char from right side."""

        if len(str_) > 0 and str_[-1] == char:
            str_ = str_[:-1]
        return str_


INSPECTOR = TypeVar('INSPECTOR')


class AbstractInspectorParser(Generic[INSPECTOR], ABC):
    """Base interface for all inspectors parsers."""

    def __init__(self, inspector_cls: Type[INSPECTOR]) -> None:
        self.inspector_cls = inspector_cls

    @abstractmethod
    def parse(self, token: Token) -> Union[INSPECTOR, None]:
        """Signature of parse method which creates inspector based on given token."""


class HasInspectorParser(AbstractInspectorParser[HasInspector]):
    """Creates HasInspector based on token created from 'has(name:=value)' string."""

    NAME = 'has'
    SEPARATOR = ':='

    def parse(self, token: Token) -> Union[HasInspector, None]:
        """Creates inspector."""

        if token.name == self.NAME:
            body_chunks = [chunk.strip() for chunk in token.body.split(self.SEPARATOR)]

            if len(body_chunks) == 0:
                raise MessageDefinitionError(f'Structure cannot be parsed: '
                                             f'inspector "{token.name}({token.body})" is empty')

            return self.inspector_cls(*body_chunks)

        return None


class NotHasInspectorParser(HasInspectorParser, AbstractInspectorParser[NotHasInspector]):
    """Creates NotHasInspector based on token created from 'notHas(name:=value)' string."""

    NAME = 'notHas'
    SEPARATOR = ':='

    def parse(self, token: Token) -> Union[NotHasInspector, None]:
        """Creates inspector."""

        return super().parse(token)


class PassesInspectorParser(AbstractInspectorParser[PassesInspector]):
    """Creates PassesInspector based on token created from 'passes(function_name)' string."""

    NAME = 'passes'

    def parse(self, token: Token) -> Union[PassesInspector, None]:

        if token.name == self.NAME:

            body = token.body.strip()

            if body == '':
                raise MessageDefinitionError(f'Structure cannot be parsed: '
                                             f'inspector "{token.name}({token.body})" is empty')

            return self.inspector_cls(body)

        return None


inspector_parsers = [
    HasInspectorParser(HasInspector),
    NotHasInspectorParser(NotHasInspector),
    PassesInspectorParser(PassesInspector),
]


class MessageParser:
    """Creates AwaitedMessage based on given token."""

    FIND_BY_SECTION_NAME = 'findBy'
    VERIFY_BY_SECTION_NAME = 'verifyBy'

    def __init__(self, message_cls: Type[AwaitedMessage]) -> None:
        self.message_cls = message_cls

    def parse(self, token: Token) -> AwaitedMessage:
        """Creates awaited message based on given tokens."""

        if token.name == '':
            raise MessageDefinitionError('Structure cannot be parsed: name of message cannot be empty string')

        finders_tokens, verifiers_tokens = [], []

        for body_token in token.body:

            if body_token.name == self.FIND_BY_SECTION_NAME:
                finders_tokens = body_token.body
            elif body_token.name == self.VERIFY_BY_SECTION_NAME:
                verifiers_tokens = body_token.body
            else:
                raise MessageDefinitionError(f'Structure cannot be parsed: unknown "{body_token.name}" section name '
                                             f'in "{token.name}" message')

        if len(finders_tokens) == 0:
            raise MessageDefinitionError(f'Structure cannot be parsed: there is required at least one inspector '
                                         f'in required "{self.FIND_BY_SECTION_NAME}" section in "{token.name}" message')

        message = self.message_cls(
            name=token.name,
            find_by=self._parse_inspectors(finders_tokens, token.name),
            verify_by=self._parse_inspectors(verifiers_tokens, token.name)
        )

        return message

    @staticmethod
    def _parse_inspectors(tokens: List[Token], message_name: str) -> List[AbstractInspector]:
        """Parses list of inspectors."""

        inspectors = []

        for token in tokens:

            for parser in inspector_parsers:
                inspector = parser.parse(token)
                if inspector is not None:
                    inspectors.append(inspector)
                    break
            else:
                raise MessageDefinitionError(f'Structure cannot be parsed: there is unknown inspector "{token.name}" '
                                             f'in "{message_name}" message')

        return inspectors


class Parser:
    """Creates object to parse token tree."""

    @staticmethod
    def parse(tokens: List[Token]) -> List[AwaitedMessage]:
        """Parses given tokens."""

        message_parser = MessageParser(AwaitedMessage)
        return [message_parser.parse(token) for token in tokens]
